  2325   * Handle the main states of rcl parser
  2326   * @param parser parser structure
  2327   * @return true if chunk has been parsed and false in case of error
  2328   */
  2329  static bool
  2330  ucl_state_machine (struct ucl_parser *parser)
  2331  {
  2332          ucl_object_t *obj, *macro_args;
  2333          struct ucl_chunk *chunk = parser->chunks;
  2334          const unsigned char *p, *c = NULL, *macro_start = NULL;
  2335          unsigned char *macro_escaped;
  2336          size_t macro_len = 0;
  2337          struct ucl_macro *macro = NULL;
  2338          bool next_key = false, end_of_object = false, ret;
