  2340          if (parser->top_obj == NULL) {
  2341                  parser->state = UCL_STATE_INIT;
  2342          }
  2343
  2344          p = chunk->pos;
  2345          while (chunk->pos < chunk->end) {
  2346                  switch (parser->state) {
  2347                  case UCL_STATE_INIT:
  2348                          /*
  2349                           * At the init state we can either go to the parse array or object
  2350                           * if we got [ or { correspondingly or can just treat new data as
  2351                           * a key of newly created object
  2352                           */
  2353                          if (!ucl_skip_comments (parser)) {
  2354                                  parser->prev_state = parser->state;
  2355                                  parser->state = UCL_STATE_ERROR;
  2356                                  return false;
  2357                          }
  2358                          else {
  2359                                  bool seen_obrace = false;
  2360
