  2362                                  while (p < chunk->end && ucl_test_character (*p,
  2363                                                  UCL_CHARACTER_WHITESPACE_UNSAFE)) {
  2364                                          ucl_chunk_skipc (chunk, p);
  2365                                  }
  2366
  2367                                  p = chunk->pos;
  2368
  2369                                  if (p < chunk->end) {
  2370                                          if (*p == '[') {
  2371                                                  parser->state = UCL_STATE_VALUE;
  2372                                                  ucl_chunk_skipc (chunk, p);
  2373                                                  seen_obrace = true;
  2374                                          }
  2375                                          else {
  2376
  2377                                                  if (*p == '{') {
  2378                                                          ucl_chunk_skipc (chunk, p);
  2379                                                          parser->state = UCL_STATE_KEY_OBRACE;
  2380                                                          seen_obrace = true;
  2381                                                  }
  2382                                                  else {
  2383                                                          parser->state = UCL_STATE_KEY;
  2384                                                  }
  2385                                          }
  2386                                  }
  2387
