  2389                                          if (parser->state == UCL_STATE_VALUE) {
  2390                                                  obj = ucl_parser_add_container (NULL, parser, true, 0,
  2391                                                                  seen_obrace);
  2392                                          }
  2393                                          else {
  2394                                                  obj = ucl_parser_add_container (NULL, parser, false, 0,
  2395                                                                  seen_obrace);
  2396                                          }
  2397
  2398                                          if (obj == NULL) {
  2399                                                  return false;
  2400                                          }
  2401
  2402                                          parser->top_obj = obj;
  2403                                          parser->cur_obj = obj;
  2404                                  }
  2405
  2406                          }
  2407                          break;
  2408                  case UCL_STATE_KEY:
  2409                  case UCL_STATE_KEY_OBRACE:
  2410                          /* Skip any spaces */
  2411                          while (p < chunk->end && ucl_test_character (*p, UCL_CHARACTER_WHITESPACE_UNSAFE)) {
  2412                                  ucl_chunk_skipc (chunk, p);
  2413                          }
  2414                          if (p == chunk->end || *p == '}') {
  2415                                  /* We have the end of an object */
  2416                                  parser->state = UCL_STATE_AFTER_VALUE;
  2417                                  continue;
  2418                          }
