  2420                                  /* No objects are on stack, but we want to parse a key */
  2421                                  ucl_set_err (parser, UCL_ESYNTAX, "top object is finished but the parser "
  2422                                                  "expects a key", &parser->err);
  2423                                  parser->prev_state = parser->state;
  2424                                  parser->state = UCL_STATE_ERROR;
  2425                                  return false;
  2426                          }
  2427                          if (!ucl_parse_key (parser, chunk, &next_key, &end_of_object)) {
  2428                                  parser->prev_state = parser->state;
  2429                                  parser->state = UCL_STATE_ERROR;
  2430                                  return false;
  2431                          }
  2432
  2433                          if (end_of_object) {
  2434                                  p = chunk->pos;
  2435                                  parser->state = UCL_STATE_AFTER_VALUE;
  2436                                  continue;
  2437                          }
