  2462                                  parser->prev_state = parser->state;
  2463                                  parser->state = UCL_STATE_ERROR;
  2464                                  return false;
  2465                          }
  2466                          /* State is set in ucl_parse_value call */
  2467                          p = chunk->pos;
  2468                          break;
  2469                  case UCL_STATE_AFTER_VALUE:
  2470                          if (!ucl_parse_after_value (parser, chunk)) {
  2471                                  parser->prev_state = parser->state;
  2472                                  parser->state = UCL_STATE_ERROR;
  2473                                  return false;
  2474                          }
  2475
  2476                          if (parser->stack != NULL) {
  2477                                  if (parser->stack->obj->type == UCL_OBJECT) {
  2478                                          parser->state = UCL_STATE_KEY;
  2479                                  }
  2480                                  else {
  2481                                          /* Array */
  2482                                          parser->state = UCL_STATE_VALUE;
  2483                                  }
  2484                          }
  2485                          else {
  2486                                  /* Skip everything at the end */
  2487                                  return true;
  2488                          }
  2489
  2490                          p = chunk->pos;
  2491                          break;
  2492                  case UCL_STATE_MACRO_NAME:
  2493                          if (parser->flags & UCL_PARSER_DISABLE_MACRO) {
  2494                                  if (!ucl_skip_macro_as_comment (parser, chunk)) {
  2495                                          /* We have invalid macro */
  2496                                          ucl_create_err (&parser->err,
  2497                                                          "error at %s:%d at column %d: invalid macro",
  2498                                                          chunk->fname ? chunk->fname : "memory",
  2499                                                          chunk->line,
  2500                                                          chunk->column);
  2501                                          parser->state = UCL_STATE_ERROR;
  2502                                          return false;
  2503                                  }
  2504                                  else {
  2505                                          p = chunk->pos;
  2506                                          parser->state = parser->prev_state;
  2507                                  }
  2508                          }
  2509                          else {
  2510                                  if (!ucl_test_character (*p, UCL_CHARACTER_WHITESPACE_UNSAFE) &&
  2511                                                  *p != '(') {
  2512                                          ucl_chunk_skipc (chunk, p);
  2513                                  }
  2514                                  else {
  2515                                          if (c != NULL && p - c > 0) {
  2516                                                  /* We got macro name */
  2517                                                  macro_len = (size_t) (p - c);
  2518                                                  HASH_FIND (hh, parser->macroes, c, macro_len, macro);
  2519                                                  if (macro == NULL) {
  2520                                                          ucl_create_err (&parser->err,
  2521                                                                          "error at %s:%d at column %d: "
  2522                                                                          "unknown macro: '%.*s', character: '%c'",
  2523                                                                          chunk->fname ? chunk->fname : "memory",
  2524                                                                          chunk->line,
  2525                                                                          chunk->column,
  2526                                                                          (int) (p - c),
  2527                                                                          c,
  2528                                                                          *chunk->pos);
  2529                                                          parser->state = UCL_STATE_ERROR;
  2530                                                          return false;
  2531                                                  }
  2532                                                  /* Now we need to skip all spaces */
  2533                                                  SKIP_SPACES_COMMENTS(parser, chunk, p);
  2534                                                  parser->state = UCL_STATE_MACRO;
  2535                                          }
  2536                                          else {
  2537                                                  /* We have invalid macro name */
  2538                                                  ucl_create_err (&parser->err,
  2539                                                                  "error at %s:%d at column %d: invalid macro name",
  2540                                                                  chunk->fname ? chunk->fname : "memory",
  2541                                                                  chunk->line,
  2542                                                                  chunk->column);
  2543                                                  parser->state = UCL_STATE_ERROR;
  2544                                                  return false;
  2545                                          }
  2546                                  }
  2547                          }
  2548                          break;
  2549                  case UCL_STATE_MACRO:
  2550                          if (*chunk->pos == '(') {
  2551                                  macro_args = ucl_parse_macro_arguments (parser, chunk);
  2552                                  p = chunk->pos;
  2553                                  if (macro_args) {
  2554                                          SKIP_SPACES_COMMENTS(parser, chunk, p);
  2555                                  }
  2556                          }
  2557                          else {
  2558                                  macro_args = NULL;
  2559                          }
  2560                          if (!ucl_parse_macro_value (parser, chunk, macro,
  2561                                          &macro_start, &macro_len)) {
  2562                                  parser->prev_state = parser->state;
  2563                                  parser->state = UCL_STATE_ERROR;
  2564                                  return false;
  2565                          }
  2566                          macro_len = ucl_expand_variable (parser, &macro_escaped,
  2567                                          macro_start, macro_len);
  2568                          parser->state = parser->prev_state;
  2569
  2570                          if (macro_escaped == NULL && macro != NULL) {
  2571                                  if (macro->is_context) {
  2572                                          ret = macro->h.context_handler (macro_start, macro_len,
  2573                                                          macro_args,
  2574                                                          parser->top_obj,
  2575                                                          macro->ud);
  2576                                  }
  2577                                  else {
  2578                                          ret = macro->h.handler (macro_start, macro_len, macro_args,
  2579                                                          macro->ud);
  2580                                  }
  2850  }
