  2852  bool
  2853  ucl_parser_add_chunk_full (struct ucl_parser *parser, const unsigned char *data,
  2854                  size_t len, unsigned priority, enum ucl_duplicate_strategy strat,
  2855                  enum ucl_parse_type parse_type)
  2856  {
  2857          struct ucl_chunk *chunk;
  2858          struct ucl_parser_special_handler *special_handler;
  2859
  2860          if (parser == NULL) {
  2861                  return false;
  2862          }
  2863
  2864          if (data == NULL && len != 0) {
  2865                  ucl_create_err (&parser->err, "invalid chunk added");
  2866                  return false;
  2867          }
  2868
  2869          if (parser->state != UCL_STATE_ERROR) {
  2870                  chunk = UCL_ALLOC (sizeof (struct ucl_chunk));
  2871                  if (chunk == NULL) {
  2872                          ucl_create_err (&parser->err, "cannot allocate chunk structure");
  2873                          return false;
  2874                  }
  2875
  2876                  memset (chunk, 0, sizeof (*chunk));
  2877
  2878                  /* Apply all matching handlers from the first to the last */
  2879                  LL_FOREACH (parser->special_handlers, special_handler) {
  2880                          if ((special_handler->flags & UCL_SPECIAL_HANDLER_PREPROCESS_ALL) ||
  2881                                          (len >= special_handler->magic_len &&
  2882                                           memcmp (data, special_handler->magic, special_handler->magic_len) == 0)) {
  2883                                  unsigned char *ndata = NULL;
  2884                                  size_t nlen = 0;
  2885
  2886                                  if (!special_handler->handler (parser, data, len, &ndata, &nlen,
  2887                                                  special_handler->user_data)) {
  2888                                          ucl_create_err (&parser->err, "call for external handler failed");
  2889                                          return false;
  2890                                  }
  2891
  2892                                  struct ucl_parser_special_handler_chain *nchain;
  2893                                  nchain = UCL_ALLOC (sizeof (*nchain));
  2894                                  nchain->begin = ndata;
  2895                                  nchain->len = nlen;
  2896                                  nchain->special_handler = special_handler;
  2897
  2898                                  /* Free order is reversed */
  2899                                  LL_PREPEND (chunk->special_handlers, nchain);
  2900
  2901                                  data = ndata;
  2902                                  len = nlen;
  2903                          }
  2904                  }
  2905
  2906                  if (parse_type == UCL_PARSE_AUTO && len > 0) {
  2907                          /* We need to detect parse type by the first symbol */
  2908                          if ((*data & 0x80) == 0x80 && (*data >= 0xdc && *data <= 0xdf)) {
  2909                                  parse_type = UCL_PARSE_MSGPACK;
  2910                          }
  2911                          else if (*data == '(') {
  2912                                  parse_type = UCL_PARSE_CSEXP;
  2913                          }
  2914                          else {
  2915                                  parse_type = UCL_PARSE_UCL;
  2916                          }
  2917                  }
  2918
  2919                  chunk->begin = data;
  2920                  chunk->remain = len;
  2921                  chunk->pos = chunk->begin;
  2922                  chunk->end = chunk->begin + len;
  2923                  chunk->line = 1;
  2924                  chunk->column = 0;
  2925                  chunk->priority = priority;
  2926                  chunk->strategy = strat;
  2927                  chunk->parse_type = parse_type;
  2928
  2929                  if (parser->cur_file) {
  2930                          chunk->fname = strdup (parser->cur_file);
  2931                  }
  2932
  2933                  LL_PREPEND (parser->chunks, chunk);
  2934                  parser->recursion ++;
  2935
  2936                  if (parser->recursion > UCL_MAX_RECURSION) {
  2937                          ucl_create_err (&parser->err, "maximum include nesting limit is reached: %d",
  2938                                          parser->recursion);
  2939                          return false;
  2940                  }
  2941
  2942                  if (len > 0) {
  2943                          /* Need to parse something */
  2944                          switch (parse_type) {
  2945                          default:
  2946                          case UCL_PARSE_UCL:
  2947                                  return ucl_state_machine (parser);
  2948                          case UCL_PARSE_MSGPACK:
  2949                                  return ucl_parse_msgpack (parser);
  2950                          case UCL_PARSE_CSEXP:
  2951                                  return ucl_parse_csexp (parser);
  2952                          }
  2953                  }
  2954                  else {
  2955                          /* Just add empty chunk and go forward */
  2956                          if (parser->top_obj == NULL) {
  2957                                  /*
  2958                                   * In case of empty object, create one to indicate that we've
  2959                                   * read something
  2960                                   */
  2961                                  parser->top_obj = ucl_object_new_full (UCL_OBJECT, priority);
  2962                          }
  2963
  2964                          return true;
  2965                  }
  2966          }
  2967
  2968          ucl_create_err (&parser->err, "a parser is in an invalid state");
  2969
  2970          return false;
  2971  }
