  2999  ucl_parser_insert_chunk (struct ucl_parser *parser, const unsigned char *data,
  3000                  size_t len)
  3001  {
  3002          if (parser == NULL || parser->top_obj == NULL) {
  3003                  return false;
  3004          }
  3005
  3006          bool res;
  3007          struct ucl_chunk *chunk;
  3008
  3009          int state = parser->state;
  3010          parser->state = UCL_STATE_INIT;
  3011
  3012          /* Prevent inserted chunks from unintentionally closing the current object */
  3013          if (parser->stack != NULL && parser->stack->next != NULL) {
  3014                  parser->stack->e.params.level = parser->stack->next->e.params.level;
  3015          }
  3016
  3017          res = ucl_parser_add_chunk_full (parser, data, len, parser->chunks->priority,
  3018                                          parser->chunks->strategy, parser->chunks->parse_type);
  3019
  3020          /* Remove chunk from the stack */
  3021          chunk = parser->chunks;
  3022          if (chunk != NULL) {
  3023                  parser->chunks = chunk->next;
  3024                  ucl_chunk_free (chunk);
  3025                  parser->recursion --;
  3026          }
  3027
  3028          parser->state = state;
  3029
  3030          return res;
  3031  }
